-- State transitions declared for Registration (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION event.registrations_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           COALESCE(NEW."state"::text, '') IN ('cancel', 'done', 'draft', 'open')
       ) THEN
        RAISE WARNING 'state_transition_not_declared: registrations.state % -> %', OLD."state", NEW."state";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS registrations_state_transition_check ON event.registrations;
CREATE TRIGGER registrations_state_transition_check
    BEFORE UPDATE OF "state" ON event.registrations
    FOR EACH ROW EXECUTE FUNCTION event.registrations_state_transition_check();
